(function(){'use strict';
let lang='ar';try{lang=localStorage.getItem('miyar-language')==='en'?'en':'ar';}catch{}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),t=(a,b)=>lang==='ar'?a:b;
const pages={privacy:['الخصوصية','Privacy'],terms:['شروط التجربة','Pilot terms'],dpa:['مسودة اتفاقية المعالجة','DPA outline'],retention:['الاحتفاظ بالبيانات','Retention'],security:['الأمان والمواءمة','Security posture'],methodology:['كيف يقرر معيار؟','How Miyar decides'],status:['حالة الخدمات','Live status'],changes:['التحديثات','Changelog'],recovery:['استعادة الحساب','Account recovery']};
const p=(a,b)=>'<p>'+t(a,b)+'</p>',h=(a,b)=>'<h2>'+t(a,b)+'</h2>',table=(headers,rows)=>'<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>i?'<td>'+x+'</td>':'<th scope="row">'+x+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>';
function content(key){
if(key==='privacy')return p('هذا الإشعار يصف التشغيل الحالي للتجربة، بتاريخ 29 سبتمبر 2026. مسؤول التواصل للمشروع: أديب نور عبر صفحة الفريق. تحدد الجهة المتعاقدة ومسؤول حماية البيانات قبل أي تجربة ببيانات موظفين حقيقية.','This notice describes the pilot as of 29 September 2026. Project contact: Adeeb Noor through the team page. The contracting entity and data-protection contact must be designated before any pilot using real employee data.')+h('ما الذي يعالج؟','What is processed?')+p('المسودات والخطط والإعدادات المحلية تحفظ في متصفح جهازك حتى تمسحها أو تمسح بيانات الموقع. حساب المؤسسة يرسل البريد وكلمة المرور إلى الخادم للتحقق؛ تحفظ كلمة المرور كتجزئة Argon2 ولا تحفظ كنص صريح. الطلبات والمراجعات المؤسسية تحفظ في PostgreSQL مع سجل القرارات.','Device drafts, plans and local settings stay in your browser until you remove them or clear site storage. Organization login sends email and password to the API for verification; passwords are stored as Argon2 hashes, not plaintext. Organization requests and reviews are stored in PostgreSQL with decision history.')+p('لا ترسل تجربة AI العامة النص أو النتائج إلى قاعدة بيانات معيار. بعد موافقتك، ترسل الهدف والمجال والمستوى والقيود إلى Google Gemini للتضمين والتوليد. يحتفظ معيار بعدادات استخدام ومعرّف شبكة مشتق باستخدام HMAC لمنع إساءة الاستخدام. قد يحتفظ مزود الخدمة بسجلات وفق شروطه؛ لم نتحقق هنا من مدة احتفاظه أو موقع معالجة كل طلب.','Public expert AI does not save prompts or results in Miyar’s database. With your consent, the objective, field, level and constraints go to Google Gemini for embedding and generation. Miyar retains usage counters and an HMAC-derived network identifier for abuse prevention. The provider may retain logs under its terms; its retention period and processing location for each request have not been independently verified here.')+h('الاستضافة والمشاركة','Hosting and recipients')+p('تُستضاف الواجهة على GitHub Pages، والخدمة الحالية على Render في فرانكفورت. لا ندّعي استضافة جميع المعالجة داخل المملكة. قد تسجّل منصات الاستضافة بيانات اتصال تقنية. لا توجد تحليلات تسويقية أو إرسال تلقائي لملاحظات الخبراء. تنزيل PDF يرسل محتوى المسودة إلى خادم التصدير لمعالجته في الذاكرة.','The frontend is hosted on GitHub Pages and the current API on Render in Frankfurt. We do not claim that all processing takes place in Saudi Arabia. Hosting platforms may log technical connection data. There is no marketing analytics or automatic expert-feedback submission. PDF export sends draft content to the export API for in-memory processing.')+h('التحكم والحقوق','Control and requests')+p('استخدم بيانات افتراضية في التجربة العامة. يمكنك رفض إرسال AI والاستمرار بالأدوات المحلية، وتصدير مسوداتك أو مسح بيانات الموقع من المتصفح. لطلبات الوصول أو التصحيح أو الحذف في مساحة المؤسسة، تواصل مع مسؤول الجهة وصفحة الفريق. تخضع إزالة سجلات القرارات لسياسة الجهة والالتزامات المطبقة، ولا نعد بحذف سجل تدقيق غير قابل للتعديل تلقائيًا.','Use synthetic data in the public pilot. You may decline AI processing and continue with local tools, export drafts or clear browser site data. For access, correction or deletion in an organization workspace, contact the organization administrator and the team page. Removal of decision records is subject to the organization’s policy and applicable obligations; immutable audit records are not promised to be automatically deleted.');
if(key==='terms')return '<div class="notice">'+t('ضوابط تجربة بحثية ومراجعة منتج؛ لا تمثل عقد خدمة مؤسسية أو ضمان امتثال.','Research and product-review pilot rules; not an enterprise service contract or a compliance warranty.')+'</div>'+p('اختبر ببيانات افتراضية ومعلومات مصرح لك باستخدامها. نتائج المسمى والترميز والتقييم والتعويض مقترحات تتطلب مراجعة بشرية. لا تستخدم النتيجة وحدها لاتخاذ قرار توظيف أو أجر أو فصل أو اعتماد تنظيمي.','Test with synthetic information and material you are authorized to use. Title, coding, evaluation and compensation outputs are proposals requiring human review. Do not use an output alone for employment, pay, dismissal or regulatory approval decisions.')+p('لا تُرفع بيانات موظفين أو بيانات شخصية حساسة إلى التجربة العامة. لا تمثل المراجع القديمة إصدارًا رسميًا حاليًا. لا يقدم معيار أسعار سوق أو منهجية تقييم تجارية مرخصة تلقائيًا. قد تتوقف خدمة التجربة أو تبلغ حد الاستخدام المعلن.','Do not upload employee records or sensitive personal information to the public pilot. Historical references are not represented as the current official edition. Miyar does not automatically provide market salary data or a licensed commercial evaluation method. The pilot service may be unavailable or reach its published usage limit.')+p('قبل الاستخدام المؤسسي، يلزم اتفاق منفصل يحدد الجهة والنطاق والصلاحيات والتوافر والمسؤوليات والموقع الجغرافي والاحتفاظ والمعالجة. هذه الصفحة ليست توقيعًا على ذلك الاتفاق.','Enterprise use requires a separate agreement defining the parties, scope, permissions, availability, responsibilities, locations, retention and processing. This page is not a signature on that agreement.');
if(key==='dpa')return '<div class="pending">'+t('مسودة عناصر للمراجعة القانونية والتعاقدية. غير موقعة ولا يجوز اعتبارها اتفاقية نافذة.','Outline for legal and contractual review. Unsigned and not an effective agreement.')+'</div>'+table([t('البند','Clause'),t('ما يجب إكماله قبل التعاقد','Required before agreement')],[['1',t('تسمية جهة التحكم والمعالج وممثليهما ووسائل التواصل.','Name controller, processor, representatives and contacts.')],['2',t('غرض المعالجة، الفئات والبيانات، المدة، التعليمات الموثقة والأساس النظامي الذي تحدده جهة التحكم.','Define processing purpose, categories, data, duration, documented instructions and controller-selected legal basis.')],['3',t('توثيق GitHub وRender وGoogle وأي معالج فرعي آخر، والمواقع والانتقالات والموافقات اللازمة.','Document GitHub, Render, Google and other subprocessors, locations, transfers and required approvals.')],['4',t('اعتماد صلاحيات الأدوار والتشفير والاستجابة للحوادث ومسار الإبلاغ والجدول الزمني المتفق عليه.','Agree role permissions, encryption, incident response, notification route and timelines.')],['5',t('تحديد مدد الاحتفاظ لكل فئة، ومساعدة أصحاب البيانات، وآلية إعادة البيانات وحذفها عند انتهاء الخدمة، ومعالجة السجلات والنسخ الاحتياطية.','Set retention by category, data-subject assistance, return/deletion on termination, and treatment of audit records and backups.')],['6',t('اعتماد التدقيق، وإثبات الضوابط، وإدارة التغييرات، والجهة المسؤولة عن الاستفسارات والنزاعات.','Agree audit rights, control evidence, change management and responsibility for questions and disputes.')]]);
if(key==='retention')return p('هذا جدول السلوك الحالي، وليس تعهدًا بمدد لم تُنفّذ. تُعتمد سياسة المؤسسة قبل إدخال بيانات حقيقية.','This table describes current behavior, not unimplemented retention promises. An organization policy must be approved before real data is introduced.')+table([t('الفئة','Category'),t('المكان والمدة الحالية','Location and current lifetime'),t('الإزالة / المسؤولية','Removal / responsibility')],[[t('مسودات وخطط محلية','Local drafts and plans'),t('localStorage في الجهاز، بلا حذف زمني تلقائي.','Browser localStorage; no automatic time-based deletion.'),t('المستخدم: تصدير ثم حذف المسودة أو مسح بيانات الموقع.','User: export then delete the draft or clear site storage.')],[t('رمز الجلسة','Session token'),t('ذاكرة المتصفح؛ صلاحية 30 دقيقة.','Browser memory; 30-minute validity.'),t('الخروج، انتهاء الجلسة، أو إبطالها من الخادم.','Logout, expiry or server revocation.')],[t('هدف AI ونتيجته','AI prompt and output'),t('ذاكرة الطلب في معيار؛ سياسات Google مستقلة ولم تعتمد لهذه التجربة المؤسسية بعد.','Miyar request memory; Google policies are separate and not yet approved for an enterprise pilot.'),t('لا يُحفظ النص في قاعدة تجربة الخبراء. راجع شروط المزود قبل بيانات حقيقية.','Expert endpoint does not store text in its database. Review provider terms before real data.')],[t('عدادات تجربة AI','Expert AI counters'),t('معرّفات HMAC لشبكة الاتصال؛ السجلات القديمة تنظف أثناء الاستخدام التالي بعد 24 ساعة.','HMAC network identifiers; records older than 24 hours are cleaned during subsequent usage.'),t('العداد العام يعاد ضبطه يوميًا؛ لا يحتوي نص الهدف.','Global counter resets daily; no prompt text.')],[t('سجلات المؤسسة والتدقيق','Organization and audit records'),t('PostgreSQL؛ لا توجد سياسة حذف آلي مطبقة حاليًا.','PostgreSQL; no automatic deletion policy currently implemented.'),t('تُحدد المدة والإجراءات تعاقديًا مع مراعاة سلامة السجل والالتزامات المطبقة.','Agree duration and procedure contractually, preserving record integrity and applicable obligations.')],[t('ملفات التصدير','Export files'),t('ملفات على جهاز من نزّلها؛ التصدير الخادمي يعالج في الذاكرة.','Files on the recipient’s device; server export processes in memory.'),t('المستخدم/الجهة يديران النسخ والصلاحيات.','User/organization controls copies and access.')]]);
if(key==='security')return '<div class="notice">'+t('خريطة جاهزية وليست شهادة امتثال PDPL أو NCA.','Readiness mapping, not PDPL or NCA certification.')+'</div>'+table([t('المجال','Area'),t('منفذ في المنتج','Implemented'),t('متطلبات الجهة المتبقية','Remaining organization work')],[[t('الهوية والصلاحيات','Identity and access'),t('أدوار خادمية، عزل الجهات، كلمات مرور Argon2، إبطال الجلسات، استعادة بمساعدة مسؤول.','Server roles, tenant isolation, Argon2, session revocation, administrator-assisted recovery.'),t('اعتماد مصفوفة الأدوار؛ SSO وMFA غير منفذين.','Approve role matrix; SSO and MFA are not implemented.')],[t('حماية البيانات','Data protection'),t('HTTPS، تقليل البيانات، عدم حفظ نصوص تجربة AI، توضيح التخزين المحلي.','HTTPS, data minimization, no expert-prompt database retention, local-storage disclosure.'),t('تقييم الأثر والمسوغ والانتقالات والمواقع ومدد الاحتفاظ والمعالجين الفرعيين.','Assess impact, legal basis, transfers, locations, retention and subprocessors.')],[t('السجلات والاستجابة','Logs and response'),t('سجل قرار غير قابل للتعديل، معرّف طلب وإحصاءات تشغيل لا تتضمن نص المدخلات.','Immutable decision history, request identifiers and operational counters without input text.'),t('تسمية مسؤول الحوادث، المراقبة الخارجية، النسخ الاحتياطي واختبار الاستعادة.','Assign incident owner, external monitoring, backups and restore exercises.')],[t('دورة الحساب','Account lifecycle'),t('12–256 محرفًا؛ 5 محاولات فاشلة لكل حساب/شبكة في 15 دقيقة؛ رابط استعادة 15 دقيقة يستخدم مرة واحدة.','12–256 characters; 5 failed attempts per account/network in 15 minutes; single-use 15-minute recovery link.'),t('تتحقق الجهة من الهوية قبل تسليم رابط الاستعادة؛ لا إرسال بريد آلي.','Organization verifies identity before delivering recovery links; no automatic email.')]] )+h('المراجع الرسمية','Official references')+'<ul><li><a href="https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/PDPL">SDAIA · PDPL</a></li><li><a href="https://dgp.sdaia.gov.sa/wps/portal/pdp/knowledgecenter/details/ElaborationandDevelopingPrivacyPolicyGuideline">SDAIA · Privacy policy guidance</a></li><li><a href="https://nca.gov.sa/en/regulatory-documents/controls-list/ecc/">NCA · ECC 2-2024</a></li></ul>';
if(key==='methodology')return p('معيار أداة تصميم ومراجعة قرارات القوى العاملة. لكل مسار مصدر وحدود مستقلة.','Miyar supports workforce decision design and review. Each path has its own evidence and limits.')+table([t('المسار','Path'),t('آلية القرار','Decision process'),t('حدوده','Limits')],[[t('الترشيح المرجعي المحلي','Local reference recommendation'),t('قواعد قابلة للفحص للمهمة والمجال والمستوى، ثم ربط بمرجع التصنيف.','Inspectable task, field and level rules followed by taxonomy linkage.'),t('ليس Embedding أو LLM، ولا يقدم احتمال ثقة إحصائيًا.','Not embeddings or an LLM; no statistical confidence probability.')],[t('الهدف الاستراتيجي بالذكاء الاصطناعي','Strategic-objective AI'),t('Gemini embedding يقارن الهدف بعينة من 5 أهداف هندسية. عتبة المسار 0.85؛ يستخدم LLM للتوليد والتحقق.','Gemini embeddings compare the objective with 5 engineering objective examples. Route threshold: 0.85; an LLM generates and validates proposals.'),t('التشابه ليس احتمال ثقة. عدم مطابقة العينة لا يثبت أن الوظيفة جديدة. الرمز الرسمي لا يُخترع. المسمى والمستوى بحاجة لمراجعة.','Similarity is not confidence. No corpus match does not prove a new occupation. Official codes are not invented. Title and level need review.')],[t('مطابقة المهارات','Skill matching'),t('قاموس محدود وطبقة دلالية اختيارية مستقلة.','Limited dictionary with a separate optional semantic layer.'),t('19 مهارة وربطان مؤلفان فقط. semanticEnabled هنا لا يصف حالة محرك الهدف الاستراتيجي.','19 skills and only 2 authored crosswalks. semanticEnabled here does not describe strategic-objective AI.')],[t('التخطيط والتعويض','Planning and compensation'),t('حسابات تعتمد على افتراضات المستخدم ونطاق راتب الجهة.','Calculations from user assumptions and organization salary bands.'),t('لا تنبؤ معتمد ولا بيانات سوق مختلقة ولا قرار أجر آلي.','No validated forecast, fabricated market data or automatic pay decision.')]])+p('المراجع المرفقة: 5,041 مهنة من إصدار يناير 2019 و599 تخصصًا تعليميًا من 2020. تتطلب القرارات الحالية مراجعة أحدث مرجع رسمي. معايير 0.75 و0.03 المنشورة لمطابقة المهارات منفصلة وتجريبية؛ لا توجد نتائج معايرة بخبراء منشورة بعد.','Bundled references: 5,041 occupations from January 2019 and 599 education specializations from 2020. Current decisions require checking the latest official reference. The published 0.75 and 0.03 skill-matching thresholds are separate and experimental; no expert calibration results have been published yet.')+p('سجل جلسة المحرك سجل واجهة مؤقت، وليس سجل الاعتماد المؤسسي غير القابل للتعديل. يحفظ الاعتماد فقط لحسابات الجهة وفق الصلاحيات والإصدار المراجع.','The engine session log is temporary UI history, not the immutable organization approval ledger. Approvals require organization accounts, permissions and the reviewed revision.');
if(key==='changes')return '<p>v'+esc(window.MIYAR_RELEASE?.version)+' · 2026-09-29</p><ul>'+[t('فصل حالة AI الاستراتيجي عن مطابقة المهارات وتوحيد الإصدار.','Separate strategic AI from skill matching and unify release identity.'),t('تحميل المراجع عند الحاجة، وتحسين الأمان واستعادة الحساب بمساعدة المسؤول.','Load references on demand, harden security and add administrator-assisted recovery.'),t('تصحيح سجل تشغيل المحرك وإضافة صفحات الثقة والجاهزية.','Repair engine session history and add trust/readiness pages.')].map(x=>'<li>'+x+'</li>').join('')+'<p><a href="./audit-remediation.html">'+t('سجل الاستجابة لتقرير الفريق الاستشاري','Consultant audit response register')+'</a></p>';
if(key==='recovery')return p('اطلب رابط استعادة من مسؤول مؤسستك بعد التحقق من هويتك. الرابط يستخدم مرة واحدة وينتهي بعد 15 دقيقة. لا ننشئ حسابًا جديدًا ولا نرسل بريدًا تلقائيًا.','Request a recovery link from your organization administrator after identity verification. Links are single-use and expire after 15 minutes. This does not create an account or send email automatically.')+'<form id="recovery-form"><label>'+t('رمز الاستعادة','Recovery token')+'<input id="recovery-token" type="password" autocomplete="off" required></label><label>'+t('كلمة المرور الجديدة — 12 محرفًا على الأقل','New password — at least 12 characters')+'<input id="recovery-password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>'+t('تأكيد كلمة المرور','Confirm password')+'<input id="recovery-confirm" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button type="submit">'+t('تعيين كلمة المرور','Set password')+'</button><p role="status" id="recovery-status"></p></form>';
return p('افحص حالة الاتصال الحالية. قد تحتاج الخدمة نحو دقيقة للاستيقاظ بعد الخمول. الجاهزية تعني التهيئة وليست إثبات جودة الترشيح أو اعتمادًا مؤسسيًا.','Check current connectivity. The service may need about a minute to wake after idling. Readiness describes configuration, not recommendation quality or organization approval.')+'<button id="check-live" type="button">'+t('افحص الخدمات الآن','Check services now')+'</button><div id="live-status" aria-live="polite"></div>';
}
async function check(){const target=document.getElementById('live-status'),button=document.getElementById('check-live');button.disabled=true;target.textContent=t('جارٍ الاتصال بالخدمة…','Contacting the service…');try{const base=window.MIYAR_CONFIG.apiBase;const values=await Promise.all(['/health','/api/v1/analyze/strategic/status','/api/v1/review/strategic/status'].map(async path=>{const r=await fetch(base+path,{signal:AbortSignal.timeout(90000)});if(!r.ok)throw Error(String(r.status));return r.json();}));if(!target.isConnected)return;const [health,ai,review]=values;const yes=b=>t(b?'مهيأ':'غير مهيأ',b?'Configured':'Not configured');target.innerHTML=p('آخر فحص: '+new Date().toLocaleString('ar-SA-u-ca-gregory'),'Last checked: '+new Date().toLocaleString('en-GB'))+table([t('الخدمة','Service'),t('الحالة الحالية','Observed status')],[[t('الواجهة / الخادم','Frontend / API'),esc(window.MIYAR_RELEASE?.version)+' / '+esc(health.version)+(health.version===window.MIYAR_RELEASE?.version?' ✓':' · '+t('اختلاف إصدار','Version mismatch'))],[t('هوية البناء — الواجهة / الخادم','Build identity — frontend / API'),esc(window.MIYAR_RELEASE?.buildId)+' / '+esc(health.buildId)+(health.buildId===window.MIYAR_RELEASE?.buildId?' ✓':' · '+t('اختلاف بناء','Build mismatch'))],[t('الهدف الاستراتيجي Embedding + LLM','Strategic objective Embedding + LLM'),yes(ai.configured)],[t('تجربة الخبراء','Expert trial'),t(review.enabled?'مفتوحة':'مغلقة',review.enabled?'Open':'Closed')+' · '+esc(review.remainingToday)+' / '+esc(review.dailyLimit)],[t('مطابقة المهارات الدلالية المستقلة','Separate semantic skill matching'),yes(health.services?.skillsSemantic?.enabled??health.services?.semanticEnabled)],[t('توليد KPI الخادمي','Server KPI generation'),yes(health.services?.kpiGenerationEnabled)],[t('الاعتمادات','Approvals'),t('تتطلب حساب الجهة وصلاحياتها','Require organization account and permissions')],[t('المراقبة','Monitoring'),t('هذا الفحص لحظي؛ ليس قياس توافر تاريخيًا.','This is a point-in-time check, not historical uptime.')]]);}catch(e){if(target.isConnected)target.innerHTML='<p role="alert">'+t('تعذر الفحص الآن. راجع اتصال الشبكة ثم حاول مجددًا. لم نستبدل الفشل بحالة نجاح.','Check failed. Verify connectivity and retry. No successful status is substituted for a failure.')+'</p>';}finally{if(button.isConnected)button.disabled=false;}}
function render(){const raw=location.hash.slice(1),key=Object.hasOwn(pages,raw.split('?')[0])?raw.split('?')[0]:'privacy';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('trust-language').textContent=lang==='ar'?'English':'العربية';document.getElementById('trust-version').textContent=window.MIYAR_RELEASE?.version||'';document.getElementById('trust-nav').innerHTML=Object.entries(pages).map(([id,title])=>'<a href="#'+id+'" '+(id===key?'aria-current="page"':'')+'>'+t(...title)+'</a>').join('');document.getElementById('trust-main').innerHTML='<h1>'+t(...pages[key])+'</h1>'+content(key);document.title=t(...pages[key])+' | MIYAR';document.getElementById('check-live')?.addEventListener('click',check);
if(key==='recovery'){const incoming=new URLSearchParams(raw.split('?')[1]||'').get('token');if(incoming){document.getElementById('recovery-token').value=incoming;history.replaceState(null,'',location.pathname+location.search+'#recovery');}document.getElementById('recovery-form').onsubmit=async e=>{e.preventDefault();const status=document.getElementById('recovery-status'),password=document.getElementById('recovery-password').value;if(password!==document.getElementById('recovery-confirm').value){status.textContent=t('كلمتا المرور غير متطابقتين.','Passwords do not match.');return;}const button=e.target.querySelector('button');button.disabled=true;try{const r=await fetch(window.MIYAR_CONFIG.apiBase+'/api/v1/auth/recovery/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:document.getElementById('recovery-token').value,newPassword:password}),signal:AbortSignal.timeout(90000)});if(!r.ok)throw Error(String(r.status));e.target.reset();status.innerHTML=t('حُفظت كلمة المرور وأُبطلت الجلسات السابقة.','Password saved and previous sessions revoked.')+' <a href="./index.html#enterprise/connection">'+t('تسجيل الدخول','Sign in')+'</a>';}catch{status.textContent=t('لم تُستكمل الاستعادة. قد يكون الرابط منتهيًا أو مستخدمًا أو الخدمة غير متاحة. اطلب رابطًا جديدًا من المسؤول.','Recovery did not complete. The link may be expired/used or the service unavailable. Request a new link from your administrator.');}finally{button.disabled=false;}};}}
document.getElementById('trust-language').onclick=()=>{lang=lang==='ar'?'en':'ar';try{localStorage.setItem('miyar-language',lang);}catch{}render();};window.addEventListener('hashchange',render);render();})();
